export function findTextureByKeyword(keyword: string): TextureData | null {
    const lowerKey = keyword.toLowerCase();
    
    // 1. Precise Match on ID
    // 2. Tag match
    
    const values = Object.values(TEXTURE_LIBRARY);
    
    // Prioritize "Wood" category if keyword includes wood
    // (Simple heuristic)
    
    const candidates = values.filter(tex => {
        if (tex.name.toLowerCase().includes(lowerKey)) return true;
        if (tex.tags.some(t => t.toLowerCase() === lowerKey)) return true;
        return false;
    });
    
    if (candidates.length > 0) {
        // Return random or first? Random is better for variety
        return candidates[Math.floor(Math.random() * candidates.length)];
    }
    
    return null;
}
